import re

from openlibrary.catalog.merge.normalize import normalize

# fields needed for merge process:
# title_prefix, title, subtitle, isbn, publish_country, lccn, publishers, publish_date, number_of_pages, authors

re_amazon_title_paren = re.compile(r'^(.*) \([^)]+?\)$')

isbn_match = 85


def set_isbn_match(score):
    isbn_match = score


def build_titles(title: str):
    """
    Uses a full title to create normalized and short title versions.

    :param str title: Full title of an edition
    :rtype: dict
    :return: An expanded set of title variations
    """
    normalized_title = normalize(title)
    titles = [title, normalized_title]
    t2 = []
    for t in titles:
        t = normalize(t)
        if t.startswith('the '):
            t2.append(t[4:])
        elif t.startswith('a '):
            t2.append(t[2:])
    titles += t2

    if re_amazon_title_paren.match(normalized_title):
        t2 = []
        for t in titles:
            t = normalize(t)
            m = re_amazon_title_paren.match(t)
            if m:
                t2.append(m.group(1))
                t2.append(normalize(m.group(1)))
        titles += t2

    return {
        'full_title': title,
        'normalized_title': normalized_title,
        'titles': list(set(titles)),
        'short_title': normalized_title[:25],
    }


def add_db_name(rec: dict) -> None:
    """Add a comparable name to each author in an edition, in place."""
    for author in rec.get('authors') or []:
        date = author.get('date')
        if not date and ('birth_date' in author or 'death_date' in author):
            date = (author.get('birth_date') or '') + '-' + (
                author.get('death_date') or ''
            )
        author['db_name'] = ' '.join((author['name'], date)) if date else author['name']


def expand_record(rec: dict) -> dict:
    """Build the title, ISBN, and author fields used by edition comparison."""
    full_title = rec.get('title') or rec.get('full_title', '')
    if rec.get('title') and rec.get('subtitle'):
        full_title += ' ' + rec['subtitle']
    rec['full_title'] = full_title
    expanded = build_titles(full_title)
    expanded['isbn'] = []
    for field in ('isbn', 'isbn_10', 'isbn_13'):
        values = rec.get(field) or []
        expanded['isbn'].extend([values] if isinstance(values, str) else values)
    if rec.get('publish_country') not in (None, '   ', '|||'):
        expanded['publish_country'] = rec['publish_country']
    for field in (
        'lccn',
        'publishers',
        'publish_date',
        'number_of_pages',
        'authors',
        'contribs',
    ):
        if field in rec and rec[field] is not None:
            value = rec[field]
            if field in ('authors', 'contribs'):
                value = [author.copy() for author in value]
            expanded[field] = value
    add_db_name(expanded)
    for contributor in expanded.get('contribs') or []:
        add_db_name({'authors': [contributor]})
    return expanded


def within(a, b, distance):
    return abs(a - b) <= distance


def compare_country(e1, e2):
    field = 'publish_country'
    if field not in e1 or field not in e2:
        return (field, 'value missing', 0)
    if e1[field] == e2[field]:
        return (field, 'match', 40)
    # West Berlin (wb) == Germany (gw)
    if e1[field] in ('gw ', 'wb ') and e2[field] in ('gw ', 'wb '):
        return (field, 'match', 40)
    return (field, 'mismatch', -205)


def compare_lccn(e1, e2):
    field = 'lccn'
    if field not in e1 or field not in e2:
        return (field, 'value missing', 0)
    if e1[field] == e2[field]:
        return (field, 'match', 200)
    return (field, 'mismatch', -320)


def compare_date(e1, e2):
    if 'publish_date' not in e1 or 'publish_date' not in e2:
        return ('date', 'value missing', 0)
    if e1['publish_date'] == e2['publish_date']:
        return ('date', 'exact match', 200)
    try:
        e1_pub = int(e1['publish_date'])
        e2_pub = int(e2['publish_date'])
        if within(e1_pub, e2_pub, 2):
            return ('date', '+/-2 years', -25)
        else:
            return ('date', 'mismatch', -250)
    except ValueError as TypeError:
        return ('date', 'mismatch', -250)


def compare_isbn10(e1, e2):
    if len(e1['isbn']) == 0 or len(e2['isbn']) == 0:
        return ('ISBN', 'missing', 0)
    for i in e1['isbn']:
        for j in e2['isbn']:
            if i == j:
                return ('ISBN', 'match', isbn_match)
    return ('ISBN', 'mismatch', -225)


